    26→/**
    27→ * Backoff configuration for reconnection
    28→ */
    29→interface BackoffConfig {
    30→  /** Initial delay in milliseconds */
    31→  initialDelayMs: number;
    32→  /** Maximum delay in milliseconds */
    33→  maxDelayMs: number;
    34→  /** Multiplier for exponential backoff */
    35→  multiplier: number;
    36→}
    37→
    38→/**
    39→ * Default backoff configuration
    40→ * Starts at 1s, doubles each time, max 30s
    41→ */
    42→const DEFAULT_BACKOFF: BackoffConfig = {
    43→  initialDelayMs: 1000,
    44→  maxDelayMs: 30000,
    45→  multiplier: 2,
    46→};
