    48→/**
    49→ * Ping interval to keep connection alive (30 seconds)
    50→ */
    51→const PING_INTERVAL_MS = 30000;
    52→
    53→/**
    54→ * Pending request with resolve/reject handlers
    55→ */
    56→interface PendingRequest {
    57→  type: string;
    58→  resolve: (response: CompanionResponse) => void;
    59→  reject: (error: Error) => void;
