    71→export interface ConnectionServiceCallbacks {
    72→  /** Called when authentication is required */
    73→  onAuthRequired?: () => void;
    74→  /** Called when authentication fails */
    75→  onAuthFailed?: (reason: string) => void;
    76→  /** Called when connection is lost */
