    82→/**
    83→ * ConnectionService class
    84→ *
    85→ * Singleton service for managing WebSocket connection to the RustRide desktop app.
    86→ * Handles connection lifecycle, message routing, and store updates.
    87→ */
    88→export class ConnectionService {
    89→  private static instance: ConnectionService | null = null;
    90→
    91→  private ws: WebSocket | null = null;
    92→  private serverUrl: string | null = null;
    93→  private reconnectAttempt = 0;
    94→  private reconnectTimeoutId: ReturnType<typeof setTimeout> | null = null;
    95→  private pingIntervalId: ReturnType<typeof setInterval> | null = null;
    96→  private pendingRequests: Map<string, PendingRequest> = new Map();
    97→  private requestIdCounter = 0;
    98→  private callbacks: ConnectionServiceCallbacks = {};
    99→  private isIntentionalDisconnect = false;
   100→  private backoffConfig: BackoffConfig = DEFAULT_BACKOFF;
   101→
   102→  /**
   103→   * Private constructor for singleton pattern
   104→   */
   105→  private constructor() {}
   106→
   107→  /**
   108→   * Get the singleton instance
   109→   */
   110→  public static getInstance(): ConnectionService {
   111→    if (!ConnectionService.instance) {
   112→      ConnectionService.instance = new ConnectionService();
   113→    }
   114→    return ConnectionService.instance;
   115→  }
   116→
   117→  /**
   118→   * Set callbacks for connection events
   119→   */
   120→  public setCallbacks(callbacks: ConnectionServiceCallbacks): void {
   121→    this.callbacks = callbacks;
   122→  }
   123→
   124→  /**
   125→   * Connect to a RustRide server
   126→   * @param url WebSocket URL (e.g., ws://192.168.1.100:9876)
   127→   */
   128→  public connect(url: string): Promise<void> {
   129→    return new Promise((resolve, reject) => {
   130→      if (this.ws?.readyState === WebSocket.OPEN) {
   131→        this.disconnect();
   132→      }
   133→
   134→      this.serverUrl = url;
   135→      this.isIntentionalDisconnect = false;
   136→      this.reconnectAttempt = 0;
   137→
   138→      // Update connection store
   139→      const connectionStore = useConnectionStore.getState();
   140→      connectionStore.connect(url);
   141→
   142→      try {
   143→        this.ws = new WebSocket(url);
   144→        this.setupWebSocketHandlers(resolve, reject);
   145→      } catch (error) {
   146→        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
   147→        connectionStore.setError('CONNECTION_FAILED', errorMessage);
   148→        reject(error);
   149→      }
   150→    });
   151→  }
   152→
   153→  /**
   154→   * Set up WebSocket event handlers
   155→   */
   156→  private setupWebSocketHandlers(
   157→    onConnected: () => void,
   158→    onConnectFailed: (error: Error) => void,
   159→  ): void {
   160→    if (!this.ws) return;
   161→
   162→    this.ws.onopen = () => {
   163→      const connectionStore = useConnectionStore.getState();
   164→      connectionStore.setConnected();
   165→      this.reconnectAttempt = 0;
   166→      this.startPingInterval();
   167→      onConnected();
   168→    };
   169→
   170→    this.ws.onclose = event => {
   171→      this.handleDisconnect(event.reason || 'Connection closed');
   172→    };
   173→
   174→    this.ws.onerror = () => {
   175→      const error = new Error('WebSocket connection error');
   176→      const connectionStore = useConnectionStore.getState();
   177→
   178→      if (connectionStore.status === 'connecting') {
   179→        connectionStore.setError('CONNECTION_ERROR', error.message);
   180→        onConnectFailed(error);
   181→      }
   182→
   183→      this.callbacks.onError?.(error);
   184→    };
   185→
   186→    this.ws.onmessage = event => {
   187→      this.handleMessage(event.data);
   188→    };
   189→  }
   190→
   191→  /**
   192→   * Handle WebSocket disconnection
   193→   */
   194→  private handleDisconnect(reason: string): void {
   195→    this.stopPingInterval();
   196→    this.clearPendingRequests('Connection closed');
   197→
   198→    const connectionStore = useConnectionStore.getState();
   199→    connectionStore.disconnect();
   200→
   201→    // Reset metrics subscription state
   202→    const metricsStore = useMetricsStore.getState();
   203→    metricsStore.setSubscribed(false);
   204→
   205→    this.callbacks.onDisconnected?.(reason);
   206→
   207→    // Attempt reconnection if not intentional
   208→    if (!this.isIntentionalDisconnect && this.serverUrl) {
   209→      this.scheduleReconnect();
   210→    }
   211→  }
   212→
   213→  /**
   214→   * Schedule a reconnection attempt with exponential backoff
   215→   */
   216→  private scheduleReconnect(): void {
   217→    const connectionStore = useConnectionStore.getState();
   218→
   219→    // Check if we've exceeded max attempts
   220→    if (!connectionStore.reconnectAttempts) {
   221→      connectionStore.resetReconnectAttempts();
   222→    }
   223→
   224→    if (connectionStore.reconnectAttempts >= connectionStore.maxReconnectAttempts) {
   225→      connectionStore.setError('MAX_RECONNECT_ATTEMPTS', 'Maximum reconnection attempts reached');
   226→      return;
   227→    }
   228→
   229→    // Calculate backoff delay
   230→    const delay = Math.min(
   231→      this.backoffConfig.initialDelayMs *
   232→        Math.pow(this.backoffConfig.multiplier, this.reconnectAttempt),
   233→      this.backoffConfig.maxDelayMs,
   234→    );
   235→
   236→    this.reconnectAttempt++;
   237→    connectionStore.incrementReconnectAttempts();
   238→
   239→    this.reconnectTimeoutId = setTimeout(() => {
   240→      if (this.serverUrl && !this.isIntentionalDisconnect) {
   241→        this.connect(this.serverUrl).catch(() => {
   242→          // Error handling is done in connect()
   243→        });
   244→      }
   245→    }, delay);
   246→  }
   247→
   248→  /**
   249→   * Disconnect from the server
   250→   */
   251→  public disconnect(): void {
   252→    this.isIntentionalDisconnect = true;
   253→    this.cancelReconnect();
   254→    this.stopPingInterval();
   255→    this.clearPendingRequests('Disconnected by user');
