   263→ * Get heart rate zone based on max HR percentage
   264→ * Zone 1: 50-60%, Zone 2: 60-70%, Zone 3: 70-80%, Zone 4: 80-90%, Zone 5: 90-100%
   265→ */
   266→export function getHeartRateZone(hr: number, maxHr: number): HeartRateZone {
   267→  if (maxHr <= 0) {
   268→    return 'zone1';
   269→  }
   270→  const percentage = (hr / maxHr) * 100;
   271→
   272→  if (percentage < 60) {
   273→    return 'zone1';
   274→  }
   275→  if (percentage < 70) {
   276→    return 'zone2';
   277→  }
   278→  if (percentage < 80) {
   279→    return 'zone3';
   280→  }
   281→  if (percentage < 90) {
   282→    return 'zone4';
   283→  }
   284→  return 'zone5';
   285→}
   286→
