   155→    const newOffset = append ? state.pagination.offset + rides.length : rides.length;
   156→
   157→    set({
   158→      rides: newRides,
   159→      pagination: {
   160→        ...state.pagination,
   161→        offset: newOffset,
   162→        total,
   163→        hasMore: newOffset < total,
   164→      },
   165→      isLoading: false,
   166→      isLoadingMore: false,
   167→      error: null,
   168→      lastFetchedAt: Date.now(),
   169→    });
   170→  },
   171→
   172→  clearRides: () => {
   173→    set({
   174→      rides: [],
   175→      pagination: {
