   177→        limit: PAGE_SIZE,
   178→        total: 0,
   179→        hasMore: false,
   180→      },
   181→    });
   182→  },
   183→
   184→  // Loading states
   185→  setLoading: (isLoading: boolean) => {
   186→    set({ isLoading });
   187→  },
   188→
   189→  setLoadingMore: (isLoadingMore: boolean) => {
   190→    set({ isLoadingMore });
   191→  },
   192→
   193→  setError: (error: string | null) => {
