   366→
   367→  switch (filter) {
   368→    case 'week': {
   369→      const start = new Date(now);
   370→      start.setDate(start.getDate() - 7);
   371→      return { start, end };
   372→    }
   373→    case 'month': {
   374→      const start = new Date(now);
   375→      start.setMonth(start.getMonth() - 1);
   376→      return { start, end };
   377→    }
   378→    case 'year': {
   379→      const start = new Date(now);
   380→      start.setFullYear(start.getFullYear() - 1);
