     1→/**
     2→ * Settings Store
     3→ *
     4→ * Manages user preferences including unit system (metric/imperial),
     5→ * display preferences, and other app settings.
     6→ *
     7→ * Settings are persisted to AsyncStorage for cross-session retention.
     8→ */
     9→
    10→import { create } from 'zustand';
    11→import AsyncStorage from '@react-native-async-storage/async-storage';
    12→import type { AppSettings } from '@/types';
    13→
    14→/**
    15→ * Unit system types
    16→ */
    17→export type UnitSystem = 'metric' | 'imperial';
    18→
    19→/**
    20→ * Haptic feedback intensity
    21→ */
