    23→
    24→/**
    25→ * Theme preference
    26→ */
    27→export type ThemePreference = 'system' | 'light' | 'dark';
    28→
    29→/**
    30→ * Storage key for settings
    31→ */
    32→const SETTINGS_STORAGE_KEY = '@rustride/settings';
    33→
    34→/**
    35→ * Default app settings
    36→ */
    37→const defaultSettings: AppSettings = {
    38→  units: 'metric',
    39→  keepScreenAwake: true,
    40→  hapticFeedback: 'medium',
    41→  theme: 'system',
    42→};
    43→
    44→/**
    45→ * Settings store state
    46→ */
    47→interface SettingsState {
    48→  /** Current app settings */
    49→  settings: AppSettings;
    50→
    51→  /** Whether settings have been loaded from storage */
    52→  isLoaded: boolean;
    53→
    54→  /** Whether settings are currently being saved */
    55→  isSaving: boolean;
    56→}
    57→
    58→/**
    59→ * Settings store actions
    60→ */
    61→interface SettingsActions {
    62→  /** Load settings from AsyncStorage */
    63→  loadSettings: () => Promise<void>;
    64→
    65→  /** Set the unit system (metric/imperial) */
    66→  setUnits: (units: UnitSystem) => Promise<void>;
    67→
    68→  /** Toggle the unit system between metric and imperial */
    69→  toggleUnits: () => Promise<void>;
    70→
    71→  /** Set keep screen awake preference */
    72→  setKeepScreenAwake: (enabled: boolean) => Promise<void>;
    73→
    74→  /** Set haptic feedback intensity */
    75→  setHapticFeedback: (intensity: HapticIntensity) => Promise<void>;
    76→
    77→  /** Set theme preference */
    78→  setTheme: (theme: ThemePreference) => Promise<void>;
    79→
    80→  /** Update multiple settings at once */
    81→  updateSettings: (updates: Partial<AppSettings>) => Promise<void>;
    82→
    83→  /** Reset to default settings */
    84→  resetSettings: () => Promise<void>;
    85→}
    86→
    87→/**
    88→ * Initial settings state
    89→ */
    90→const initialState: SettingsState = {
    91→  settings: defaultSettings,
    92→  isLoaded: false,
    93→  isSaving: false,
    94→};
    95→
    96→/**
    97→ * Settings store
    98→ *
    99→ * Manages user preferences with persistence to AsyncStorage.
   100→ */
   101→export const useSettingsStore = create<SettingsState & SettingsActions>()((set, get) => ({
   102→  ...initialState,
   103→
   104→  // Load settings from AsyncStorage
   105→  loadSettings: async () => {
   106→    try {
   107→      const json = await AsyncStorage.getItem(SETTINGS_STORAGE_KEY);
   108→      if (json) {
   109→        const loaded = JSON.parse(json) as Partial<AppSettings>;
   110→        // Merge with defaults to ensure all fields exist
   111→        const settings: AppSettings = {
   112→          ...defaultSettings,
   113→          ...loaded,
   114→        };
   115→        set({ settings, isLoaded: true });
   116→      } else {
   117→        set({ isLoaded: true });
   118→      }
   119→    } catch {
   120→      // On error, use defaults
   121→      set({ isLoaded: true });
   122→    }
   123→  },
   124→
   125→  // Set the unit system
   126→  setUnits: async (units: UnitSystem) => {
   127→    const { settings } = get();
   128→    const newSettings = { ...settings, units };
   129→    set({ settings: newSettings, isSaving: true });
   130→
   131→    try {
   132→      await AsyncStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(newSettings));
   133→    } finally {
   134→      set({ isSaving: false });
   135→    }
   136→  },
   137→
   138→  // Toggle the unit system between metric and imperial
   139→  toggleUnits: async () => {
   140→    const { settings, setUnits } = get();
   141→    const newUnits: UnitSystem = settings.units === 'metric' ? 'imperial' : 'metric';
   142→    await setUnits(newUnits);
   143→  },
   144→
   145→  // Set keep screen awake preference
   146→  setKeepScreenAwake: async (enabled: boolean) => {
   147→    const { settings } = get();
   148→    const newSettings = { ...settings, keepScreenAwake: enabled };
   149→    set({ settings: newSettings, isSaving: true });
   150→
   151→    try {
   152→      await AsyncStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(newSettings));
   153→    } finally {
   154→      set({ isSaving: false });
   155→    }
   156→  },
   157→
   158→  // Set haptic feedback intensity
   159→  setHapticFeedback: async (intensity: HapticIntensity) => {
   160→    const { settings } = get();
   161→    const newSettings = { ...settings, hapticFeedback: intensity };
   162→    set({ settings: newSettings, isSaving: true });
   163→
   164→    try {
   165→      await AsyncStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(newSettings));
   166→    } finally {
   167→      set({ isSaving: false });
   168→    }
   169→  },
   170→
   171→  // Set theme preference
   172→  setTheme: async (theme: ThemePreference) => {
   173→    const { settings } = get();
   174→    const newSettings = { ...settings, theme };
   175→    set({ settings: newSettings, isSaving: true });
   176→
   177→    try {
   178→      await AsyncStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(newSettings));
   179→    } finally {
   180→      set({ isSaving: false });
   181→    }
   182→  },
   183→
   184→  // Update multiple settings at once
   185→  updateSettings: async (updates: Partial<AppSettings>) => {
   186→    const { settings } = get();
   187→    const newSettings = { ...settings, ...updates };
   188→    set({ settings: newSettings, isSaving: true });
   189→
   190→    try {
   191→      await AsyncStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(newSettings));
   192→    } finally {
   193→      set({ isSaving: false });
   194→    }
   195→  },
   196→
   197→  // Reset to default settings
   198→  resetSettings: async () => {
   199→    set({ settings: defaultSettings, isSaving: true });
   200→
   201→    try {
   202→      await AsyncStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(defaultSettings));
   203→    } finally {
   204→      set({ isSaving: false });
   205→    }
   206→  },
   207→}));
