   101→export const useSettingsStore = create<SettingsState & SettingsActions>()((set, get) => ({
   102→  ...initialState,
   103→
   104→  // Load settings from AsyncStorage
   105→  loadSettings: async () => {
   106→    try {
   107→      const json = await AsyncStorage.getItem(SETTINGS_STORAGE_KEY);
   108→      if (json) {
   109→        const loaded = JSON.parse(json) as Partial<AppSettings>;
   110→        // Merge with defaults to ensure all fields exist
   111→        const settings: AppSettings = {
   112→          ...defaultSettings,
   113→          ...loaded,
   114→        };
   115→        set({ settings, isLoaded: true });
   116→      } else {
   117→        set({ isLoaded: true });
   118→      }
   119→    } catch {
   120→      // On error, use defaults
   121→      set({ isLoaded: true });
   122→}
   123→  },
   124→
   125→  // Set the unit system
   126→  setUnits: async (units: UnitSystem) => {
   127→    const { settings } = get();
   128→    const newSettings = { ...settings, units };
   129→    set({ settings: newSettings, isSaving: true });
   130→
   131→    try {
   132→      await AsyncStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(newSettings));
   133→    } finally {
   134→      set({ isSaving: false });
   135→    }
   136→  },
   137→
