    80→
    81→  /**
    82→   * Trigger haptic feedback with a specific type
    83→   */
    84→  const triggerHaptic = useCallback(
    85→    (type: HapticFeedbackType = 'impact') => {
    86→      if (hapticIntensity === 'off') {
