     1→/**
     2→ * useHaptics Hook
     3→ *
     4→ * Provides haptic feedback functionality based on user settings.
     5→ * Uses the React Native Vibration API with intensity-based patterns.
     6→ */
     7→
     8→import { useCallback } from 'react';
     9→import { Vibration, Platform } from 'react-native';
    10→import { useSettingsStore, selectHapticFeedback } from '@/stores/settingsStore';
    11→import type { HapticIntensity } from '@/stores/settingsStore';
    12→
    13→/**
    14→ * Haptic feedback types for different interactions
    15→ */
    16→export type HapticFeedbackType =
    17→  | 'selection' // Light tap for selection/toggle
    18→  | 'impact' // Medium impact for button press
    19→  | 'notification' // Notification feedback
    20→  | 'success' // Success confirmation
    21→  | 'warning' // Warning feedback
    22→  | 'error'; // Error feedback
    23→
    24→/**
    25→ * Vibration patterns for different feedback types and intensities
    26→ * On iOS, duration values are ignored; on Android, they define vibration length in ms
    27→ */
    28→const VIBRATION_PATTERNS: Record<HapticFeedbackType, Record<Exclude<HapticIntensity, 'off'>, number>> = {
    29→  selection: {
    30→    light: 5,
    31→    medium: 10,
    32→    strong: 20,
    33→  },
    34→  impact: {
    35→    light: 10,
    36→    medium: 25,
    37→    strong: 50,
    38→  },
    39→  notification: {
    40→    light: 15,
    41→    medium: 30,
    42→    strong: 60,
    43→  },
    44→  success: {
    45→    light: 10,
    46→    medium: 20,
    47→    strong: 40,
    48→  },
    49→  warning: {
    50→    light: 20,
    51→    medium: 40,
    52→    strong: 80,
    53→  },
    54→  error: {
    55→    light: 30,
    56→    medium: 60,
    57→    strong: 100,
    58→  },
    59→};
    60→
    61→/**
    62→ * useHaptics hook
    63→ *
    64→ * Returns functions for triggering haptic feedback based on user's intensity setting.
    65→ * Respects the haptic feedback preference from settings store.
    66→ *
    67→ * @example
    68→ * ```tsx
    69→ * const { triggerHaptic, selectionHaptic, impactHaptic } = useHaptics();
    70→ *
    71→ * // Trigger with specific type
    72→ * onPress={() => {
    73→ *   impactHaptic();
    74→ *   handleAction();
    75→ * }}
    76→ * ```
    77→ */
    78→export function useHaptics() {
    79→  const hapticIntensity = useSettingsStore(selectHapticFeedback);
    80→
    81→  /**
    82→   * Trigger haptic feedback with a specific type
    83→   */
    84→  const triggerHaptic = useCallback(
    85→    (type: HapticFeedbackType = 'impact') => {
    86→      if (hapticIntensity === 'off') {
    87→        return;
    88→      }
    89→
    90→      const duration = VIBRATION_PATTERNS[type][hapticIntensity];
    91→
    92→      // Use Vibration API
    93→      // On iOS with pattern, this will use the haptic engine
    94→      // On Android, this uses the vibration motor
    95→      if (Platform.OS === 'ios') {
    96→        // iOS: Use selection feedback for light interactions
    97→        // For now, use Vibration which works on both platforms
    98→        Vibration.vibrate(duration);
    99→      } else {
   100→        Vibration.vibrate(duration);
   101→      }
   102→    },
   103→    [hapticIntensity],
   104→  );
   105→
   106→  /**
   107→   * Light tap feedback for selection/toggle actions
   108→   */
   109→  const selectionHaptic = useCallback(() => {
   110→    triggerHaptic('selection');
   111→  }, [triggerHaptic]);
   112→
   113→  /**
   114→   * Medium impact feedback for button presses
   115→   */
   116→  const impactHaptic = useCallback(() => {
   117→    triggerHaptic('impact');
   118→  }, [triggerHaptic]);
   119→
   120→  /**
   121→   * Success feedback for completed actions
   122→   */
   123→  const successHaptic = useCallback(() => {
   124→    triggerHaptic('success');
   125→  }, [triggerHaptic]);
   126→
   127→  /**
   128→   * Warning feedback for attention-required actions
   129→   */
   130→  const warningHaptic = useCallback(() => {
   131→    triggerHaptic('warning');
   132→  }, [triggerHaptic]);
   133→
   134→  /**
   135→   * Error feedback for failed actions
   136→   */
   137→  const errorHaptic = useCallback(() => {
   138→    triggerHaptic('error');
   139→  }, [triggerHaptic]);
   140→
   141→  /**
   142→   * Check if haptic feedback is enabled
   143→   */
   144→  const isHapticEnabled = hapticIntensity !== 'off';
   145→
   146→  return {
   147→    triggerHaptic,
   148→    selectionHaptic,
   149→    impactHaptic,
   150→    successHaptic,
   151→    warningHaptic,
   152→    errorHaptic,
   153→    isHapticEnabled,
   154→    hapticIntensity,
   155→  };
   156→}
   157→
   158→/**
   159→ * Trigger a one-off haptic feedback without using the hook
   160→ * Useful in callbacks where you can't use hooks
   161→ *
   162→ * @param type The type of haptic feedback
   163→ * @param intensity The intensity level (defaults to 'medium' if not provided)
   164→ */
   165→export function triggerHapticFeedback(
   166→  type: HapticFeedbackType = 'impact',
   167→  intensity: HapticIntensity = 'medium',
   168→): void {
   169→  if (intensity === 'off') {
   170→    return;
   171→  }
   172→
   173→  const duration = VIBRATION_PATTERNS[type][intensity];
   174→  Vibration.vibrate(duration);
   175→}
