     2→ * Session Store
     3→ *
     4→ * Manages workout/ride session state received from the RustRide desktop app.
     5→ * Tracks session type, status, intervals, and elapsed time.
     6→ */
     7→
     8→import { create } from 'zustand';
     9→import type { SessionStatusInfo, SessionType, SessionState } from '@/types';
    10→
    11→/**
    12→ * Interval information for structured workouts
    13→ */
    14→interface IntervalInfo {
    15→  index: number;
    16→  total: number;
    17→  name: string | null;
    18→  remainingSecs: number | null;
    19→}
    20→
    21→/**
    22→ * Session store state
    23→ */
    24→interface SessionStoreState {
    25→  // Session status
    26→  isActive: boolean;
    27→  sessionId: string | null;
    28→  sessionType: SessionType | null;
    29→  sessionState: SessionState;
    30→
    31→  // Workout details
    32→  workoutName: string | null;
    33→  workoutPath: string | null;
    34→
    35→  // Timing
    36→  elapsedSecs: number;
    37→  isPaused: boolean;
    38→
    39→  // Interval tracking
    40→  currentInterval: IntervalInfo | null;
    41→  targetPowerWatts: number | null;
    42→
    43→  // Resistance/Grade control (for free rides)
    44→  resistanceLevel: number;
    45→
    46→  // Last update
    47→  lastStatusUpdate: number | null;
    48→}
    49→
    50→/**
    51→ * Session store actions
    52→ */
    53→interface SessionActions {
    54→  // Session lifecycle
    55→  startSession: (info: SessionStatusInfo) => void;
    56→  endSession: () => void;
    57→
    58→  // Session updates
    59→  updateStatus: (info: SessionStatusInfo) => void;
    60→  setSessionState: (state: SessionState) => void;
    61→  setPaused: (isPaused: boolean) => void;
    62→
    63→  // Interval updates
    64→  updateInterval: (interval: IntervalInfo | null) => void;
    65→  setTargetPower: (watts: number | null) => void;
    66→
    67→  // Time tracking
    68→  updateElapsedTime: (secs: number) => void;
    69→
    70→  // Resistance control (for free rides)
    71→  setResistanceLevel: (level: number) => void;
    72→  adjustResistanceLevel: (delta: number) => void;
    73→
    74→  // Reset store
    75→  reset: () => void;
    76→}
    77→
    78→/**
    79→ * Initial session state
    80→ */
    81→const initialState: SessionStoreState = {
    82→  isActive: false,
    83→  sessionId: null,
    84→  sessionType: null,
    85→  sessionState: 'idle',
    86→  workoutName: null,
    87→  workoutPath: null,
    88→  elapsedSecs: 0,
    89→  isPaused: false,
    90→  currentInterval: null,
    91→  targetPowerWatts: null,
    92→  resistanceLevel: 0,
    93→  lastStatusUpdate: null,
    94→};
    95→
    96→/**
    97→ * Session store
    98→ *
    99→ * Manages workout and free ride session state with interval tracking.
   100→ */
   101→export const useSessionStore = create<SessionStoreState & SessionActions>()(set => ({
   102→  ...initialState,
   103→
   104→  // Session lifecycle
   105→  startSession: (info: SessionStatusInfo) => {
   106→    set({
   107→      isActive: true,
   108→      sessionId: info.session_id,
   109→      sessionType: info.session_type,
   110→      sessionState: 'active',
   111→      workoutName: info.workout_name ?? null,
   112→      workoutPath: info.workout_path ?? null,
   113→      elapsedSecs: info.elapsed_secs,
   114→      isPaused: info.is_paused,
   115→      currentInterval:
   116→        info.current_interval_index !== undefined
   117→          ? {
   118→              index: info.current_interval_index,
   119→              total: info.total_intervals ?? 0,
   120→              name: info.current_interval_name ?? null,
   121→              remainingSecs: info.interval_remaining_secs ?? null,
