     7→
     8→import React from 'react';
     9→import { View, Text, ActivityIndicator, StyleSheet, ViewStyle, TextStyle } from 'react-native';
    10→import { useTheme } from '@/theme';
    11→
    12→/**
    13→ * LoadingSpinner sizes
    14→ */
    15→export type LoadingSpinnerSize = 'small' | 'medium' | 'large';
    16→
    17→/**
    18→ * LoadingSpinner props
    19→ */
    20→export interface LoadingSpinnerProps {
    21→  /** Spinner size */
    22→  size?: LoadingSpinnerSize;
    23→  /** Optional loading message */
    24→  message?: string;
    25→  /** Custom spinner color */
    26→  color?: string;
    27→  /** Whether to center in the container */
    28→  centered?: boolean;
    29→  /** Whether to overlay on top of content */
    30→  overlay?: boolean;
    31→  /** Custom container style */
    32→  style?: ViewStyle;
    33→  /** Custom text style */
    34→  textStyle?: TextStyle;
    35→}
    36→
    37→/**
    38→ * Get ActivityIndicator size prop
    39→ */
    40→function getIndicatorSize(size: LoadingSpinnerSize): 'small' | 'large' {
    41→  // React Native ActivityIndicator only supports 'small' and 'large'
    42→  switch (size) {
    43→    case 'small':
    44→      return 'small';
    45→    case 'medium':
    46→    case 'large':
    47→    default:
    48→      return 'large';
    49→  }
    50→}
    51→
    52→/**
    53→ * Get custom spinner dimensions for consistent sizing
    54→ */
    55→function getSpinnerDimensions(size: LoadingSpinnerSize) {
    56→  switch (size) {
    57→    case 'small':
    58→      return { containerSize: 24, scale: 0.8 };
    59→    case 'medium':
    60→      return { containerSize: 40, scale: 1 };
    61→    case 'large':
    62→      return { containerSize: 64, scale: 1.2 };
    63→  }
    64→}
    65→
    66→/**
    67→ * LoadingSpinner Component
    68→ *
    69→ * Shows a loading spinner with optional message text.
    70→ * Useful for indicating async operations.
    71→ *
    72→ * @example
    73→ * ```tsx
    74→ * <LoadingSpinner size="large" message="Loading rides..." />
    75→ * ```
    76→ */
    77→export function LoadingSpinner({
    78→  size = 'medium',
    79→  message,
    80→  color,
    81→  centered = true,
    82→  overlay = false,
    83→  style,
    84→  textStyle,
    85→}: LoadingSpinnerProps): React.JSX.Element {
    86→  const { colors, spacing, typography } = useTheme();
    87→
    88→  const spinnerColor = color || colors.accent;
    89→  const indicatorSize = getIndicatorSize(size);
    90→  const { scale } = getSpinnerDimensions(size);
    91→
    92→  // Container styles based on props
    93→  const containerStyle: ViewStyle = {
    94→    ...(centered && styles.centered),
    95→    ...(overlay && {
    96→      ...StyleSheet.absoluteFillObject,
    97→      backgroundColor: colors.overlay,
    98→      zIndex: 1000,
    99→    }),
   100→  };
   101→
   102→  return (
   103→    <View
   104→      style={[styles.container, containerStyle, style]}
   105→      accessible
   106→      accessibilityRole="progressbar"
   107→      accessibilityLabel={message || 'Loading'}
   108→      accessibilityState={{ busy: true }}
   109→    >
   110→      <View style={[styles.spinnerContainer, { transform: [{ scale }] }]}>
   111→        <ActivityIndicator size={indicatorSize} color={spinnerColor} />
   112→      </View>
   113→      {message && (
   114→        <Text
   115→          style={[
   116→            styles.message,
   117→            typography.textStyles.body,
   118→            { color: colors.textSecondary, marginTop: spacing.md },
   119→            textStyle,
   120→          ]}
   121→        >
   122→          {message}
   123→        </Text>
   124→      )}
   125→    </View>
   126→  );
   127→}
