     1→/**
     2→ * RustRide Companion App - Theme Provider
     3→ *
     4→ * Provides theme context to the app with dark/light mode support.
     5→ * Supports system theme detection and manual theme switching.
     6→ */
     7→
     8→import React, { createContext, useContext, useMemo, useState, useEffect, useCallback } from 'react';
     9→import { useColorScheme, Appearance } from 'react-native';
    10→import { Theme, ThemeMode, darkTheme, getTheme } from './theme';
    11→
    12→/**
    13→ * Theme context value type
    14→ */
    15→interface ThemeContextValue {
    16→  /** Current theme object */
    17→  theme: Theme;
    18→  /** Current theme mode setting */
    19→  themeMode: ThemeMode;
    20→  /** Whether dark mode is active */
    21→  isDarkMode: boolean;
    22→  /** Set the theme mode */
    23→  setThemeMode: (mode: ThemeMode) => void;
    24→  /** Toggle between dark and light mode */
    25→  toggleTheme: () => void;
    26→}
    27→
    28→/**
    29→ * Theme context with default values
    30→ */
    31→const ThemeContext = createContext<ThemeContextValue>({
    32→  theme: darkTheme,
    33→  themeMode: 'system',
    34→  isDarkMode: true,
    35→  setThemeMode: () => {},
    36→  toggleTheme: () => {},
    37→});
    38→
    39→/**
    40→ * Theme provider props
    41→ */
    42→interface ThemeProviderProps {
    43→  /** Child components */
    44→  children: React.ReactNode;
    45→  /** Initial theme mode (defaults to 'system') */
    46→  initialThemeMode?: ThemeMode;
    47→}
    48→
    49→/**
    50→ * Resolve theme mode to actual dark/light based on system preference
    51→ * ColorSchemeName from React Native can be 'light', 'dark', 'unspecified', null, or undefined
    52→ */
    53→function resolveThemeMode(
    54→  mode: ThemeMode,
    55→  systemColorScheme: string | null | undefined,
    56→): 'dark' | 'light' {
    57→  if (mode === 'system') {
    58→    // Only use light mode if explicitly set to 'light'
    59→    return systemColorScheme === 'light' ? 'light' : 'dark';
    60→  }
    61→  return mode;
    62→}
    63→
    64→/**
    65→ * Theme Provider Component
    66→ *
    67→ * Wraps the app to provide theme context to all children.
    68→ * Handles system theme detection and manual theme switching.
    69→ *
    70→ * @example
    71→ * ```tsx
    72→ * <ThemeProvider>
    73→ *   <App />
    74→ * </ThemeProvider>
    75→ * ```
    76→ */
    77→export function ThemeProvider({
    78→  children,
    79→  initialThemeMode = 'system',
    80→}: ThemeProviderProps): React.JSX.Element {
    81→  // Get system color scheme
    82→  const systemColorScheme = useColorScheme();
    83→
    84→  // Current theme mode setting
    85→  const [themeMode, setThemeModeState] = useState<ThemeMode>(initialThemeMode);
    86→
    87→  // Resolve actual theme based on mode and system preference
    88→  const resolvedMode = resolveThemeMode(themeMode, systemColorScheme);
    89→  const theme = getTheme(resolvedMode);
    90→  const isDarkMode = resolvedMode === 'dark';
    91→
    92→  // Listen for system theme changes when in system mode
    93→  useEffect(() => {
    94→    if (themeMode !== 'system') {
    95→      return;
    96→    }
    97→
    98→    const subscription = Appearance.addChangeListener(({ colorScheme }) => {
    99→      // Force re-render when system theme changes
   100→      // The useColorScheme hook should handle this, but we add this as a backup
   101→      if (colorScheme !== systemColorScheme) {
   102→        // State change will trigger re-render
   103→      }
   104→    });
   105→
   106→    return () => {
   107→      subscription.remove();
   108→    };
   109→  }, [themeMode, systemColorScheme]);
   110→
   111→  // Set theme mode
   112→  const setThemeMode = useCallback((mode: ThemeMode) => {
   113→    setThemeModeState(mode);
   114→  }, []);
   115→
   116→  // Toggle between dark and light mode
   117→  const toggleTheme = useCallback(() => {
   118→    setThemeModeState(current => {
   119→      if (current === 'system') {
   120→        // If following system, switch to the opposite of current
   121→        return isDarkMode ? 'light' : 'dark';
   122→      }
   123→      // Toggle between dark and light
   124→      return current === 'dark' ? 'light' : 'dark';
   125→    });
   126→  }, [isDarkMode]);
   127→
   128→  // Memoize context value to prevent unnecessary re-renders
   129→  const contextValue = useMemo(
   130→    () => ({
   131→      theme,
   132→      themeMode,
   133→      isDarkMode,
   134→      setThemeMode,
   135→      toggleTheme,
   136→    }),
   137→    [theme, themeMode, isDarkMode, setThemeMode, toggleTheme],
   138→  );
   139→
   140→  return <ThemeContext.Provider value={contextValue}>{children}</ThemeContext.Provider>;
   141→}
   142→
   143→/**
   144→ * Hook to access the current theme
   145→ *
   146→ * @returns The current theme object
   147→ *
   148→ * @example
   149→ * ```tsx
   150→ * function MyComponent() {
   151→ *   const theme = useTheme();
   152→ *   return (
   153→ *     <View style={{ backgroundColor: theme.colors.background }}>
   154→ *       <Text style={{ color: theme.colors.textPrimary }}>Hello</Text>
   155→ *     </View>
   156→ *   );
   157→ * }
   158→ * ```
   159→ */
   160→export function useTheme(): Theme {
   161→  const context = useContext(ThemeContext);
   162→  return context.theme;
   163→}
   164→
   165→/**
   166→ * Hook to access full theme context including mode switching
   167→ *
   168→ * @returns Theme context with theme object and mode controls
   169→ *
   170→ * @example
   171→ * ```tsx
   172→ * function ThemeToggle() {
   173→ *   const { isDarkMode, toggleTheme } = useThemeContext();
   174→ *   return (
   175→ *     <Switch value={isDarkMode} onValueChange={toggleTheme} />
   176→ *   );
   177→ * }
   178→ * ```
   179→ */
   180→export function useThemeContext(): ThemeContextValue {
   181→  return useContext(ThemeContext);
   182→}
   183→
   184→/**
   185→ * Hook to check if dark mode is active
   186→ *
   187→ * @returns True if dark mode is active
   188→ */
   189→export function useIsDarkMode(): boolean {
   190→  const context = useContext(ThemeContext);
   191→  return context.isDarkMode;
   192→}
   193→
   194→/**
   195→ * Hook to get themed colors
   196→ *
   197→ * @returns The color palette for the current theme
   198→ *
   199→ * @example
   200→ * ```tsx
   201→ * function MyComponent() {
   202→ *   const colors = useColors();
   203→ *   return (
   204→ *     <View style={{ backgroundColor: colors.surface }}>
   205→ *       <Text style={{ color: colors.textPrimary }}>Hello</Text>
   206→ *     </View>
   207→ *   );
   208→ * }
   209→ * ```
   210→ */
   211→export function useColors() {
   212→  const theme = useTheme();
   213→  return theme.colors;
   214→}
   215→
   216→/**
   217→ * Hook to get themed spacing
   218→ *
   219→ * @returns The spacing values
   220→ */
   221→export function useSpacing() {
   222→  const theme = useTheme();
   223→  return theme.spacing;
   224→}
   225→
   226→/**
   227→ * Hook to get themed typography
   228→ *
   229→ * @returns The typography system
   230→ */
   231→export function useTypography() {
   232→  const theme = useTheme();
   233→  return theme.typography;
   234→}
