   103→/// Aggregated connection quality state for HUD display.
   104→#[derive(Debug, Clone, Default)]
   105→pub struct HudConnectionState {
   106→    /// Quality stats per sensor device_id.
   107→    pub quality_stats: HashMap<String, QualityStats>,
   108→    /// Whether any sensor has poor quality.
   109→    pub has_poor_quality: bool,
   110→    /// Whether any sensor has degraded (fair or poor) quality.
   111→    pub has_degraded_quality: bool,
   112→    /// Count of connected sensors.
   113→    pub connected_count: usize,
   114→    /// Worst quality level among all sensors.
   115→    pub worst_level: Option<QualityLevel>,
   116→    /// Device ID of worst sensor (for tooltip).
   117→    pub worst_device_id: Option<String>,
   118→}
   119→
   120→impl HudConnectionState {
   121→    /// Create a new HUD connection state from quality stats.
   122→    pub fn from_stats(stats: Vec<QualityStats>) -> Self {
   123→        let mut state = Self {
   124→            quality_stats: HashMap::new(),
   125→            has_poor_quality: false,
   126→            has_degraded_quality: false,
   127→            connected_count: stats.len(),
   128→            worst_level: None,
   129→            worst_device_id: None,
   130→        };
   131→
   132→        for stat in stats {
   133→            // Track worst quality
   134→            let is_worse = state.worst_level
   135→                .map(|current| stat.level < current)
   136→                .unwrap_or(true);
   137→
   138→            if is_worse {
   139→                state.worst_level = Some(stat.level);
   140→                state.worst_device_id = Some(stat.device_id.clone());
   141→            }
   142→
   143→            // Track degraded/poor flags
   144→            if stat.level == QualityLevel::Poor {
   145→                state.has_poor_quality = true;
   146→            }
   147→            if stat.level <= QualityLevel::Fair {
   148→                state.has_degraded_quality = true;
   149→            }
   150→
   151→            state.quality_stats.insert(stat.device_id.clone(), stat);
   152→        }
   153→
   154→        state
   155→    }
   156→
   157→    /// Update with new quality stats.
   158→    pub fn update(&mut self, stats: Vec<QualityStats>) {
   159→        *self = Self::from_stats(stats);
   160→    }
   161→
   162→    /// Check if the indicator should be visible.
   163→    pub fn should_show(&self) -> bool {
   164→        self.connected_count > 0
   165→    }
   166→
   167→    /// Check if warning animation should be active.
   168→    pub fn should_animate_warning(&self) -> bool {
   169→        self.has_poor_quality
   170→    }
   171→
   172→    /// Get overall signal bars (based on worst sensor).
   173→    pub fn overall_signal_bars(&self) -> u8 {
   174→        self.worst_level.map(|l| l.signal_bars()).unwrap_or(0)
   175→    }
   176→
   177→    /// Get a summary string for the connection state.
   178→    pub fn summary(&self) -> String {
   179→        if self.connected_count == 0 {
   180→            return "No sensors".to_string();
   181→        }
   182→
   183→        if self.has_poor_quality {
   184→            format!("{} sensor(s) - Poor signal", self.connected_count)
   185→        } else if self.has_degraded_quality {
   186→            format!("{} sensor(s) - Degraded signal", self.connected_count)
   187→        } else {
   188→            format!("{} sensor(s) connected", self.connected_count)
   189→        }
   190→    }
   191→}
