    29→
    30→    // T024: Configure tracing subscriber
    31→    tracing_subscriber::registry()
    32→        .with(EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")))
    33→        .with(tracing_subscriber::fmt::layer())
    34→        .init();
    35→
    36→    tracing::info!("Starting RustRide v{}", env!("CARGO_PKG_VERSION"));
    37→
    38→    // T029: Handle --headless flag for daemon mode
    39→    if args.headless {
    40→        #[cfg(target_os = "linux")]
    41→        {
    42→            run_headless_daemon(args.foreground);
    43→        }
    44→
    45→        #[cfg(not(target_os = "linux"))]
    46→        {
    47→            eprintln!("Error: --headless mode is only supported on Linux.");
