    61→    // T115: Enable accesskit for screen reader support (NVDA, VoiceOver, Orca)
    62→    // AccessKit is enabled by default in eframe 0.33+ when using egui's built-in accessibility
    63→    let options = eframe::NativeOptions {
    64→        viewport: egui::ViewportBuilder::default()
    65→            .with_inner_size([1280.0, 800.0])
    66→            .with_min_inner_size([800.0, 600.0])
    67→            .with_title("RustRide"),
    68→        // T115: AccessKit is automatically enabled in eframe 0.33+
    69→        // Screen readers can now access the UI through platform accessibility APIs
    70→        ..Default::default()
    71→    };
    72→
    73→    eframe::run_native(
    74→        "RustRide",
    75→        options,
    76→        Box::new(|cc| Ok(Box::new(app::RustRideApp::new(cc)))),
    77→    )
    78→}
