   133→/// Metrics streamer that broadcasts sensor data to companion clients at 1Hz.
   134→///
   135→/// The streamer maintains the current state of all metrics and sends
   136→/// periodic updates to the companion server's event broadcast channel.
   137→pub struct MetricsStreamer {
   138→    /// Configuration for the streamer.
   139→    config: MetricsStreamerConfig,
   140→    /// Whether the streamer is currently running.
   141→    is_running: Arc<RwLock<bool>>,
   142→    /// Current metrics state.
   143→    metrics: Arc<RwLock<StreamingMetrics>>,
   144→    /// When the session started (for elapsed time calculation).
