   146→    /// Channel to send events to the companion server.
   147→    event_tx: broadcast::Sender<CompanionEvent>,
   148→    /// Handle for the broadcast loop task.
   149→    broadcast_handle: Arc<RwLock<Option<JoinHandle<()>>>>,
   150→}
   151→
   152→impl MetricsStreamer {
   153→    /// Create a new metrics streamer.
   154→    ///
   155→    /// # Arguments
   156→    ///
   157→    /// * `event_tx` - Broadcast channel to send metrics events to the companion server
   158→    /// * `config` - Optional configuration for the streamer
   159→    pub fn new(
   160→        event_tx: broadcast::Sender<CompanionEvent>,
   161→        config: Option<MetricsStreamerConfig>,
   162→    ) -> Self {
   163→        Self {
   164→            config: config.unwrap_or_default(),
   165→            is_running: Arc::new(RwLock::new(false)),
   166→            metrics: Arc::new(RwLock::new(StreamingMetrics::new())),
   167→            session_start: Arc::new(RwLock::new(None)),
   168→            event_tx,
   169→            broadcast_handle: Arc::new(RwLock::new(None)),
   170→        }
   171→    }
   172→
   173→    /// Start the metrics streaming loop.
   174→    ///
   175→    /// This starts a background task that broadcasts current metrics
   176→    /// at the configured interval (default 1Hz).
   177→    pub async fn start(&self) {
   178→        if !self.config.enabled {
   179→            tracing::debug!("Metrics streamer is disabled");
   180→            return;
   181→        }
   182→
   183→        if *self.is_running.read().await {
   184→            tracing::debug!("Metrics streamer already running");
   185→            return;
   186→        }
   187→
   188→        // Set session start time
   189→        *self.session_start.write().await = Some(Utc::now());
   190→        *self.is_running.write().await = true;
   191→
   192→        // Clone state for the broadcast loop
   193→        let is_running = Arc::clone(&self.is_running);
   194→        let metrics = Arc::clone(&self.metrics);
   195→        let session_start = Arc::clone(&self.session_start);
   196→        let event_tx = self.event_tx.clone();
   197→        let interval = self.config.broadcast_interval;
   198→
   199→        // Spawn the broadcast loop
   200→        let handle = tokio::spawn(async move {
   201→            Self::run_broadcast_loop(is_running, metrics, session_start, event_tx, interval).await;
   202→        });
   203→
   204→        *self.broadcast_handle.write().await = Some(handle);
   205→
