     1→//! mDNS service advertisement for companion server discovery.
     2→//!
     3→//! Advertises the companion server on the local network using mDNS/DNS-SD
     4→//! so that mobile companion apps can automatically discover the server.
     5→//!
     6→//! The service is advertised as `_rustride._tcp.local.` with TXT records
     7→//! containing the port and protocol version.
     8→
     9→use mdns_sd::{ServiceDaemon, ServiceInfo};
    10→use std::collections::HashMap;
    11→use std::sync::Arc;
    12→use tokio::sync::RwLock;
    13→
    14→use super::server::get_local_ip;
    15→
    16→/// mDNS service type for RustRide companion server.
    17→/// Uses TCP since WebSocket runs over TCP.
    18→pub const COMPANION_SERVICE_TYPE: &str = "_rustride._tcp.local.";
    19→
    20→/// Protocol version for companion API.
    21→/// Increment this when making breaking changes to the API.
    22→pub const COMPANION_PROTOCOL_VERSION: &str = "1";
    23→
    24→/// Errors that can occur during mDNS operations.
    25→#[derive(Debug, thiserror::Error)]
    26→pub enum MdnsError {
    27→    /// Failed to create mDNS daemon.
    28→    #[error("Failed to create mDNS daemon: {0}")]
    29→    DaemonCreationFailed(String),
    30→
    31→    /// Failed to register service.
    32→    #[error("Failed to register service: {0}")]
    33→    RegistrationFailed(String),
    34→
    35→    /// Failed to unregister service.
    36→    #[error("Failed to unregister service: {0}")]
    37→    UnregistrationFailed(String),
    38→
    39→    /// Service not running.
    40→    #[error("mDNS service not running")]
    41→    NotRunning,
    42→}
    43→
    44→/// mDNS service advertiser for the companion server.
    45→///
    46→/// Handles registration and unregistration of the companion server
    47→/// as an mDNS service for automatic discovery by mobile apps.
    48→pub struct CompanionMdnsAdvertiser {
    49→    /// The mDNS daemon instance.
    50→    daemon: Arc<RwLock<Option<ServiceDaemon>>>,
    51→    /// The registered service name.
    52→    registered_name: Arc<RwLock<Option<String>>>,
    53→    /// Whether the advertiser is currently active.
    54→    is_running: Arc<RwLock<bool>>,
    55→}
    56→
    57→impl CompanionMdnsAdvertiser {
    58→    /// Create a new mDNS advertiser.
    59→    pub fn new() -> Self {
    60→        Self {
    61→            daemon: Arc::new(RwLock::new(None)),
    62→            registered_name: Arc::new(RwLock::new(None)),
    63→            is_running: Arc::new(RwLock::new(false)),
    64→        }
    65→    }
    66→
    67→    /// Start advertising the companion server.
    68→    ///
    69→    /// # Arguments
    70→    ///
    71→    /// * `port` - The port the WebSocket server is listening on.
    72→    /// * `instance_name` - Optional custom instance name. If None, generates one.
    73→    ///
    74→    /// # Returns
    75→    ///
    76→    /// Returns `Ok(())` if the service was successfully advertised.
    77→    pub async fn start(&self, port: u16, instance_name: Option<&str>) -> Result<(), MdnsError> {
    78→        // Check if already running
    79→        if *self.is_running.read().await {
    80→            tracing::debug!("mDNS advertiser already running");
    81→            return Ok(());
    82→        }
    83→
    84→        // Create mDNS daemon
    85→        let daemon = ServiceDaemon::new()
    86→            .map_err(|e| MdnsError::DaemonCreationFailed(e.to_string()))?;
    87→
    88→        // Generate service name
    89→        let service_name = instance_name
    90→            .map(|s| s.to_string())
    91→            .unwrap_or_else(|| format!("RustRide-{}", &uuid::Uuid::new_v4().to_string()[..8]));
    92→
    93→        // Get local hostname (use a sensible default)
    94→        let hostname = get_hostname();
    95→
    96→        // Get local IP for the service
    97→        let local_ip = get_local_ip();
    98→
    99→        // Build TXT record properties
   100→        let mut properties = HashMap::new();
   101→        properties.insert("port".to_string(), port.to_string());
   102→        properties.insert("version".to_string(), COMPANION_PROTOCOL_VERSION.to_string());
   103→        properties.insert("protocol".to_string(), "websocket".to_string());
   104→
   105→        // Create service info
   106→        let service_info = ServiceInfo::new(
   107→            COMPANION_SERVICE_TYPE,
   108→            &service_name,
   109→            &hostname,
   110→            &local_ip,
   111→            port,
   112→            properties,
   113→        )
   114→        .map_err(|e| MdnsError::RegistrationFailed(e.to_string()))?;
   115→
   116→        // Register the service
   117→        daemon
   118→            .register(service_info)
   119→            .map_err(|e| MdnsError::RegistrationFailed(e.to_string()))?;
   120→
   121→        // Store state
   122→        *self.daemon.write().await = Some(daemon);
   123→        *self.registered_name.write().await = Some(service_name.clone());
   124→        *self.is_running.write().await = true;
   125→
   126→        tracing::info!(
   127→            "Companion server advertised via mDNS: {}.{} on port {}",
   128→            service_name,
   129→            COMPANION_SERVICE_TYPE,
   130→            port
   131→        );
   132→
   133→        Ok(())
   134→    }
   135→
   136→    /// Stop advertising the companion server.
   137→    ///
   138→    /// Unregisters the service from mDNS and shuts down the daemon.
   139→    pub async fn stop(&self) -> Result<(), MdnsError> {
   140→        if !*self.is_running.read().await {
   141→            return Ok(());
   142→        }
   143→
   144→        // Get the daemon and service name
   145→        let daemon = self.daemon.write().await.take();
   146→        let service_name = self.registered_name.write().await.take();
   147→
   148→        if let (Some(daemon), Some(name)) = (daemon, service_name) {
   149→            // Build full service name for unregistration
   150→            let full_name = format!("{}.{}", name, COMPANION_SERVICE_TYPE);
   151→
   152→            // Attempt to unregister
   153→            if let Err(e) = daemon.unregister(&full_name) {
   154→                tracing::warn!("Failed to unregister mDNS service: {}", e);
   155→            }
   156→
   157→            // Shutdown the daemon
   158→            if let Err(e) = daemon.shutdown() {
   159→                tracing::warn!("Failed to shutdown mDNS daemon: {}", e);
   160→            }
   161→
   162→            tracing::info!("Companion server mDNS advertisement stopped");
   163→        }
   164→
   165→        *self.is_running.write().await = false;
   166→
   167→        Ok(())
   168→    }
   169→
   170→    /// Check if the advertiser is currently running.
   171→    pub async fn is_running(&self) -> bool {
   172→        *self.is_running.read().await
   173→    }
   174→
   175→    /// Get the service type being advertised.
   176→    pub fn service_type(&self) -> &'static str {
   177→        COMPANION_SERVICE_TYPE
   178→    }
   179→
   180→    /// Get the protocol version being advertised.
   181→    pub fn protocol_version(&self) -> &'static str {
   182→        COMPANION_PROTOCOL_VERSION
   183→    }
   184→}
   185→
   186→impl Default for CompanionMdnsAdvertiser {
   187→    fn default() -> Self {
   188→        Self::new()
   189→    }
   190→}
   191→
   192→impl Drop for CompanionMdnsAdvertiser {
   193→    fn drop(&mut self) {
   194→        // Attempt synchronous cleanup
   195→        // Note: This may not fully work in async context, but we try our best
   196→        if let Ok(mut is_running) = self.is_running.try_write() {
   197→            if *is_running {
   198→                if let Ok(mut daemon) = self.daemon.try_write() {
   199→                    if let Some(d) = daemon.take() {
   200→                        if let Ok(mut name) = self.registered_name.try_write() {
   201→                            if let Some(n) = name.take() {
   202→                                let full_name = format!("{}.{}", n, COMPANION_SERVICE_TYPE);
   203→                                let _ = d.unregister(&full_name);
   204→                            }
   205→                        }
   206→                        let _ = d.shutdown();
   207→                    }
   208→                }
   209→                *is_running = false;
   210→            }
   211→        }
   212→    }
   213→}
