   215→/// Get the local hostname for mDNS registration.
   216→fn get_hostname() -> String {
   217→    // Try to get the system hostname using gethostname
   218→    #[cfg(unix)]
   219→    {
   220→        use std::ffi::CStr;
   221→        let mut buf = [0i8; 256];
   222→        unsafe {
   223→            if libc::gethostname(buf.as_mut_ptr(), buf.len()) == 0 {
   224→                if let Ok(name) = CStr::from_ptr(buf.as_ptr()).to_str() {
   225→                    let clean_name = name.trim_end_matches('.');
   226→                    if !clean_name.is_empty() {
   227→                        return format!("{}.local.", clean_name);
   228→                    }
   229→                }
   230→            }
   231→        }
   232→    }
   233→
   234→    #[cfg(windows)]
   235→    {
   236→        // On Windows, use environment variable
   237→        if let Ok(name) = std::env::var("COMPUTERNAME") {
   238→            let clean_name = name.trim_end_matches('.');
   239→            if !clean_name.is_empty() {
   240→                return format!("{}.local.", clean_name);
   241→            }
   242→        }
   243→    }
   244→
   245→    // Fallback to a generated hostname
   246→    "rustride-companion.local.".to_string()
   247→}
