     1→//! Request handlers for companion server commands.
     2→//!
     3→//! Routes incoming WebSocket requests to appropriate handlers and
     4→//! returns responses. Integrates with the daemon state and workout
     5→//! engine to execute commands.
     6→//!
     7→//! ## Handler Categories
     8→//!
     9→//! - **Authentication**: PIN verification and session management
    10→//! - **Session Status**: Current workout/ride state queries
    11→//! - **Workout Control**: Pause, resume, skip, stop commands
    12→//! - **Metrics**: Real-time metrics subscription management
    13→//! - **Ride History**: Past ride queries and statistics (T007)
    14→
    15→use std::sync::{Arc, Mutex};
    16→use tokio::sync::RwLock;
    17→use tracing::{debug, info, warn};
    18→use uuid::Uuid;
    19→
    20→use super::types::{
    21→    CompanionErrorCode, CompanionEvent, CompanionRequest, CompanionResponse, RideDetailInfo,
    22→    RideSummary, SessionState, SessionStatusInfo,
    23→};
    24→use crate::daemon::state::{DaemonState, SessionType};
    25→use crate::recording::types::Ride;
    26→use crate::storage::Database;
    27→
    28→/// Handle an incoming companion request.
    29→///
    30→/// This function routes the request to the appropriate handler based
    31→/// on the request type and returns a response.
    32→///
    33→/// # Arguments
    34→///
    35→/// * `request` - The companion request to handle
    36→/// * `session_id` - The session ID of the requesting client
    37→/// * `is_authenticated` - Whether the client is authenticated
    38→/// * `daemon_state` - Optional daemon state for workout control commands
    39→/// * `database` - Optional database for ride history queries (T007)
    40→/// * `user_id` - Optional user ID for ride history queries (T007)
    41→pub async fn handle_request(
    42→    request: CompanionRequest,
    43→    session_id: Uuid,
    44→    is_authenticated: bool,
    45→    daemon_state: Option<Arc<RwLock<DaemonState>>>,
    46→    database: Option<Arc<Mutex<Database>>>,
    47→    user_id: Option<Uuid>,
    48→) -> CompanionResponse {
    49→    debug!("Handling companion request from session {}", session_id);
    50→
    51→    // Most commands require authentication
    52→    if !is_authenticated {
    53→        match &request {
    54→            CompanionRequest::Auth { .. } | CompanionRequest::Ping => {
    55→                // These don't require auth
    56→            }
    57→            _ => {
    58→                return CompanionResponse::Error {
    59→                    code: CompanionErrorCode::AuthRequired,
    60→                    message: "Authentication required".to_string(),
    61→                };
    62→            }
    63→        }
    64→    }
    65→
    66→    match request {
    67→        CompanionRequest::Auth { pin } => handle_auth(pin).await,
    68→        CompanionRequest::GetSessionStatus => handle_get_session_status(daemon_state).await,
    69→        CompanionRequest::SubscribeMetrics => handle_subscribe_metrics(session_id).await,
    70→        CompanionRequest::UnsubscribeMetrics => handle_unsubscribe_metrics(session_id).await,
    71→        CompanionRequest::WorkoutPause => handle_workout_pause(daemon_state).await,
    72→        CompanionRequest::WorkoutResume => handle_workout_resume(daemon_state).await,
    73→        CompanionRequest::WorkoutSkip => handle_workout_skip(daemon_state).await,
    74→        CompanionRequest::WorkoutStop => handle_workout_stop(daemon_state).await,
    75→        CompanionRequest::AdjustResistance { delta } => handle_adjust_resistance(delta).await,
    76→        CompanionRequest::GetRideHistory { limit, offset } => {
    77→            handle_get_ride_history(database, user_id, limit, offset).await
    78→        }
    79→        CompanionRequest::GetRideDetails { ride_id } => {
    80→            handle_get_ride_details(database, ride_id).await
    81→        }
    82→        CompanionRequest::Ping => CompanionResponse::Pong,
    83→    }
    84→}
