    27→/**
    28→ * Backoff configuration for reconnection
    29→ */
    30→interface BackoffConfig {
    31→  /** Initial delay in milliseconds */
    32→  initialDelayMs: number;
    33→  /** Maximum delay in milliseconds */
    34→  maxDelayMs: number;
    35→  /** Multiplier for exponential backoff */
    36→  multiplier: number;
    37→}
    38→
    39→/**
    40→ * Default backoff configuration
    41→ * Starts at 1s, doubles each time, max 30s
    42→ */
    43→const DEFAULT_BACKOFF: BackoffConfig = {
    44→  initialDelayMs: 1000,
    45→  maxDelayMs: 30000,
    46→  multiplier: 2,
    47→};
    48→
    49→/**
    50→ * Ping interval to keep connection alive (30 seconds)
    51→ */
    52→const PING_INTERVAL_MS = 30000;
    53→
    54→/**
    55→ * Pending request with resolve/reject handlers
    56→ */
    57→interface PendingRequest {
    58→  type: string;
    59→  resolve: (response: CompanionResponse) => void;
    60→  reject: (error: Error) => void;
    61→  timeoutId: ReturnType<typeof setTimeout>;
    62→}
    63→
    64→/**
    65→ * Request timeout in milliseconds
    66→ */
    67→const REQUEST_TIMEOUT_MS = 10000;
    68→
    69→/**
    70→ * Connection service event callbacks
    71→ */
    72→export interface ConnectionServiceCallbacks {
    73→  /** Called when authentication is required */
    74→  onAuthRequired?: () => void;
    75→  /** Called when authentication fails */
    76→  onAuthFailed?: (reason: string) => void;
    77→  /** Called when connection is lost */
    78→  onDisconnected?: (reason: string) => void;
    79→  /** Called on connection error */
    80→  onError?: (error: Error) => void;
    81→}
