    83→/**
    84→ * ConnectionService class
    85→ *
    86→ * Singleton service for managing WebSocket connection to the RustRide desktop app.
    87→ * Handles connection lifecycle, message routing, and store updates.
    88→ */
    89→export class ConnectionService {
    90→  private static instance: ConnectionService | null = null;
    91→
    92→  private ws: WebSocket | null = null;
    93→  private serverUrl: string | null = null;
    94→  private reconnectAttempt = 0;
    95→  private reconnectTimeoutId: ReturnType<typeof setTimeout> | null = null;
    96→  private pingIntervalId: ReturnType<typeof setInterval> | null = null;
    97→  private pendingRequests: Map<string, PendingRequest> = new Map();
    98→  private requestIdCounter = 0;
    99→  private callbacks: ConnectionServiceCallbacks = {};
   100→  private isIntentionalDisconnect = false;
   101→  private backoffConfig: BackoffConfig = DEFAULT_BACKOFF;
   102→
   103→  /**
   104→   * Private constructor for singleton pattern
   105→   */
   106→  private constructor() {}
   107→
   108→  /**
   109→   * Get the singleton instance
   110→   */
   111→  public static getInstance(): ConnectionService {
   112→    if (!ConnectionService.instance) {
   113→      ConnectionService.instance = new ConnectionService();
   114→    }
   115→    return ConnectionService.instance;
   116→  }
   117→
   118→  /**
   119→   * Set callbacks for connection events
   120→   */
   121→  public setCallbacks(callbacks: ConnectionServiceCallbacks): void {
   122→    this.callbacks = callbacks;
   123→  }
   124→
   125→  /**
   126→   * Connect to a RustRide server
   127→   * @param url WebSocket URL (e.g., ws://192.168.1.100:9876)
   128→   */
   129→  public connect(url: string): Promise<void> {
   130→    return new Promise((resolve, reject) => {
   131→      if (this.ws?.readyState === WebSocket.OPEN) {
   132→        this.disconnect();
   133→      }
   134→
   135→      this.serverUrl = url;
   136→      this.isIntentionalDisconnect = false;
   137→      this.reconnectAttempt = 0;
   138→
   139→      // Update connection store
   140→      const connectionStore = useConnectionStore.getState();
   141→      connectionStore.connect(url);
   142→
   143→      try {
   144→        this.ws = new WebSocket(url);
   145→        this.setupWebSocketHandlers(resolve, reject);
   146→      } catch (error) {
   147→        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
   148→        connectionStore.setError('CONNECTION_FAILED', errorMessage);
   149→        reject(error);
   150→      }
   151→    });
   152→  }
   153→
   154→  /**
   155→   * Set up WebSocket event handlers
   156→   */
   157→  private setupWebSocketHandlers(
   158→    onConnected: () => void,
   159→    onConnectFailed: (error: Error) => void,
   160→  ): void {
   161→    if (!this.ws) return;
   162→
   163→    this.ws.onopen = () => {
   164→      const connectionStore = useConnectionStore.getState();
   165→      connectionStore.setConnected();
   166→      this.reconnectAttempt = 0;
   167→      this.startPingInterval();
   168→      onConnected();
   169→    };
   170→
   171→    this.ws.onclose = event => {
   172→      this.handleDisconnect(event.reason || 'Connection closed');
   173→    };
   174→
   175→    this.ws.onerror = () => {
   176→      const error = new Error('WebSocket connection error');
   177→      const connectionStore = useConnectionStore.getState();
   178→
   179→      if (connectionStore.status === 'connecting') {
   180→        connectionStore.setError('CONNECTION_ERROR', error.message);
   181→        onConnectFailed(error);
   182→      }
   183→
   184→      this.callbacks.onError?.(error);
   185→    };
   186→
   187→    this.ws.onmessage = event => {
   188→      this.handleMessage(event.data);
   189→    };
   190→  }
   191→
   192→  /**
   193→   * Handle WebSocket disconnection
   194→   */
   195→  private handleDisconnect(reason: string): void {
   196→    this.stopPingInterval();
   197→    this.clearPendingRequests('Connection closed');
   198→
   199→    const connectionStore = useConnectionStore.getState();
   200→    connectionStore.disconnect();
   201→
   202→    // Reset metrics subscription state
   203→    const metricsStore = useMetricsStore.getState();
   204→    metricsStore.setSubscribed(false);
   205→
   206→    this.callbacks.onDisconnected?.(reason);
   207→
   208→    // Attempt reconnection if not intentional
   209→    if (!this.isIntentionalDisconnect && this.serverUrl) {
   210→      this.scheduleReconnect();
   211→    }
   212→  }
   213→
   214→  /**
   215→   * Schedule a reconnection attempt with exponential backoff
   216→   */
   217→  private scheduleReconnect(): void {
   218→    const connectionStore = useConnectionStore.getState();
   219→
   220→    // Check if we've exceeded max attempts
   221→    if (!connectionStore.reconnectAttempts) {
   222→      connectionStore.resetReconnectAttempts();
   223→    }
   224→
   225→    if (connectionStore.reconnectAttempts >= connectionStore.maxReconnectAttempts) {
   226→      connectionStore.setError('MAX_RECONNECT_ATTEMPTS', 'Maximum reconnection attempts reached');
   227→      return;
   228→    }
   229→
   230→    // Calculate backoff delay
   231→    const delay = Math.min(
   232→      this.backoffConfig.initialDelayMs *
   233→        Math.pow(this.backoffConfig.multiplier, this.reconnectAttempt),
   234→      this.backoffConfig.maxDelayMs,
   235→    );
   236→
   237→    this.reconnectAttempt++;
   238→    connectionStore.incrementReconnectAttempts();
   239→
   240→    this.reconnectTimeoutId = setTimeout(() => {
   241→      if (this.serverUrl && !this.isIntentionalDisconnect) {
   242→        this.connect(this.serverUrl).catch(() => {
   243→          // Error handling is done in connect()
   244→        });
   245→      }
   246→    }, delay);
   247→  }
   248→
   249→  /**
   250→   * Disconnect from the server
   251→   */
   252→  public disconnect(): void {
   253→    this.isIntentionalDisconnect = true;
   254→    this.cancelReconnect();
   255→    this.stopPingInterval();
   256→    this.clearPendingRequests('Disconnected by user');
   257→
   258→    if (this.ws) {
   259→      this.ws.close(1000, 'User disconnected');
   260→      this.ws = null;
   261→    }
   262→
   263→    const connectionStore = useConnectionStore.getState();
   264→    connectionStore.disconnect();
   265→
   266→    // Reset stores
