    51→
    52→/**
    53→ * MetricCard Component
    54→ *
    55→ * A card component for displaying workout metrics like power, heart rate, cadence, etc.
    56→ *
    57→ * @example
    58→ * ```tsx
    59→ * <MetricCard
    60→ *   value={250}
    61→ *   unit="W"
    62→ *   label="Power"
    63→ *   size="large"
    64→ *   accentColor={getPowerZoneColor(4)}
    65→ * />
    66→ * ```
    67→ */
    68→export function MetricCard({
    69→  value,
    70→  unit,
    71→  label,
    72→  size = 'medium',
    73→  accentColor,
    74→  targetValue,
    75→  targetLabel,
    76→  secondaryValue,
    77→  secondaryLabel,
    78→  style,
    79→  showAccentBorder = false,
    80→  ...accessibilityProps
    81→}: MetricCardProps): React.JSX.Element {
    82→  const { colors, spacing, typography, borderRadius: themeRadius } = useTheme();
    83→
    84→  // Format value for display
    85→  const displayValue = typeof value === 'number' ? value.toString() : value;
    86→
    87→  // Get size-specific styles
    88→  const sizeStyles = getSizeStyles(size, typography);
    89→
    90→  // Build dynamic styles
    91→  const cardStyle: ViewStyle = {
    92→    backgroundColor: colors.card,
    93→    borderRadius: themeRadius.md,
    94→    padding: spacing.lg,
    95→    minHeight: size === 'large' ? 160 : size === 'medium' ? 120 : 80,
    96→    ...(showAccentBorder && accentColor
    97→      ? {
    98→          borderLeftWidth: 4,
    99→          borderLeftColor: accentColor,
   100→        }
   101→      : {}),
   102→  };
   103→
   104→  const valueStyle: TextStyle = {
   105→    ...sizeStyles.value,
   106→    color: accentColor || colors.textPrimary,
   107→  };
   108→
   109→  const unitStyle: TextStyle = {
   110→    ...sizeStyles.unit,
   111→    color: colors.textSecondary,
   112→  };
   113→
   114→  const labelStyle: TextStyle = {
   115→    ...sizeStyles.label,
   116→    color: colors.textMuted,
   117→  };
   118→
   119→  // Build accessibility label
   120→  const accessibilityLabel =
   121→    accessibilityProps.accessibilityLabel ||
   122→    `${label}: ${displayValue}${unit ? ` ${unit}` : ''}`;
   123→
   124→  return (
   125→    <View
   126→      style={[styles.container, cardStyle, style]}
   127→      accessible
   128→      accessibilityRole="text"
   129→      accessibilityLabel={accessibilityLabel}
   130→      {...accessibilityProps}
   131→    >
   132→      {/* Label at top */}
   133→      <Text style={[styles.label, labelStyle]} numberOfLines={1}>
   134→        {label.toUpperCase()}
   135→      </Text>
   136→
   137→      {/* Main value row */}
   138→      <View style={styles.valueRow}>
   139→        <Text style={[styles.value, valueStyle]} numberOfLines={1} adjustsFontSizeToFit>
   140→          {displayValue}
   141→        </Text>
   142→        {unit && (
   143→          <Text style={[styles.unit, unitStyle]} numberOfLines={1}>
   144→            {unit}
   145→          </Text>
   146→        )}
   147→      </View>
   148→
   149→      {/* Secondary value (e.g., 3s average) */}
   150→      {secondaryValue !== undefined && (
   151→        <View style={styles.secondaryRow}>
   152→          <Text style={[styles.secondaryValue, { color: colors.textSecondary }]}>
   153→            {secondaryValue}
   154→          </Text>
   155→          {secondaryLabel && (
   156→            <Text style={[styles.secondaryLabel, { color: colors.textMuted }]}>
   157→              {secondaryLabel}
   158→            </Text>
   159→          )}
   160→        </View>
   161→      )}
   162→
   163→      {/* Target value (for workouts) */}
   164→      {targetValue !== undefined && (
   165→        <View style={styles.targetRow}>
   166→          <Text style={[styles.targetLabel, { color: colors.textMuted }]}>
   167→            {targetLabel || 'Target'}:
   168→          </Text>
   169→          <Text style={[styles.targetValue, { color: colors.textSecondary }]}>
   170→            {targetValue}
   171→            {unit && ` ${unit}`}
   172→          </Text>
   173→        </View>
   174→      )}
   175→    </View>
   176→  );
   177→}
