   107→ * Matches the JSON format generated by CompanionQrCode in src/companion/qr.rs
   108→ *
   109→ * Example:
   110→ * {
   111→ *   "url": "ws://192.168.1.100:9876",
   112→ *   "pin": "123456",
   113→ *   "version": "1"
   114→ * }
   115→ */
   116→export interface QrConnectionData {
   117→  /** WebSocket URL (e.g., "ws://192.168.1.100:9876") */
   118→  url: string;
   119→  /** Optional PIN for authentication (6 digits) */
   120→  pin?: string;
   121→  /** Protocol version for compatibility checking */
   122→  version: string;
   123→}
   124→
   125→/**
   126→ * Parse QR code data into connection data.
   127→ * Returns null if parsing fails.
   128→ */
   129→export function parseQrConnectionData(data: string): QrConnectionData | null {
   130→  try {
   131→    const parsed = JSON.parse(data);
   132→
   133→    // Validate required fields
   134→    if (typeof parsed.url !== 'string' || !parsed.url) {
   135→      return null;
   136→    }
   137→    if (typeof parsed.version !== 'string' || !parsed.version) {
   138→      return null;
   139→    }
   140→
   141→    // Validate URL format (must be ws:// or wss://)
   142→    if (!parsed.url.startsWith('ws://') && !parsed.url.startsWith('wss://')) {
   143→      return null;
   144→    }
   145→
   146→    // Validate PIN if present (should be 6 digits)
   147→    if (parsed.pin !== undefined && parsed.pin !== null) {
   148→      if (typeof parsed.pin !== 'string' || !/^\d{6}$/.test(parsed.pin)) {
   149→        return null;
   150→      }
   151→    }
   152→
   153→    return {
   154→      url: parsed.url,
   155→      pin: parsed.pin || undefined,
   156→      version: parsed.version,
   157→    };
   158→  } catch {
   159→    return null;
   160→  }
   161→}
