   163→/**
   164→ * Extract host and port from a WebSocket URL.
   165→ * Returns null if parsing fails.
   166→ */
   167→export function parseWebSocketUrl(wsUrl: string): { host: string; port: number } | null {
   168→  try {
   169→    // Parse using regex since React Native's URL implementation may be incomplete
   170→    const match = wsUrl.match(/^wss?:\/\/([^:/]+)(?::(\d+))?/);
   171→    if (!match) {
   172→      return null;
   173→    }
   174→
   175→    const host = match[1];
   176→    const port = match[2] ? parseInt(match[2], 10) : 9876; // Default port
   177→
   178→    if (!host || isNaN(port)) {
   179→      return null;
   180→    }
   181→
   182→    return { host, port };
   183→  } catch {
   184→    return null;
   185→  }
   186→}
